    "level": "l1",
    "level_label": "Level 1",
    "number": 36,
    "rule_body": "Line graphs show how continuous data changes over time (temperature, sales, patient heart rate). Time is plotted along the horizontal axis. Read points by looking across to vertical axis.",
    "rule_heading": "Plot Points &amp; Join with Straight Lines",
    "strand_name": "Handling Data",
    "strand_theme": "cyan",
    "subject": "maths",
    "subject_label": "Maths",
    "svg_html": "<svg viewBox=\"74 34 292 124\" width=\"100%\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\">\n\n          <g transform=\"translate(60, 20)\">\n            <line x1=\"20\" y1=\"110\" x2=\"300\" y2=\"110\" stroke=\"#334155\" stroke-width=\"2\"/>\n            <line x1=\"20\" y1=\"20\" x2=\"20\" y2=\"110\" stroke=\"#334155\" stroke-width=\"2\"/>\n            <polyline points=\"40,90 100,70 160,80 220,40 280,30\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n            <circle cx=\"40\" cy=\"90\" r=\"4\" fill=\"#2563eb\"/><circle cx=\"100\" cy=\"70\" r=\"4\" fill=\"#2563eb\"/><circle cx=\"160\" cy=\"80\" r=\"4\" fill=\"#2563eb\"/><circle cx=\"220\" cy=\"40\" r=\"4\" fill=\"#2563eb\"/><circle cx=\"280\" cy=\"30\" r=\"4\" fill=\"#2563eb\"/>\n            <text x=\"160\" y=\"130\" font-size=\"10\" font-weight=\"700\" fill=\"#0f172a\" text-anchor=\"middle\">Months (Jan to May) → Overall Upward Trend</text>\n          </g>\n</svg>",
