    "level_label": "Level 1 / 2",
    "number": 22,
    "rule_body": "Speaker Notes Pane: Area underneath each slide where the presenter writes their talking script. In 'Presenter View', notes are visible on the speaker's laptop screen while the audience only sees the slides.",
    "rule_heading": "Visible to Speaker Only",
    "strand_name": "Creating Content",
    "strand_theme": "orange",
    "subject": "digital",
    "subject_label": "Digital Skills",
    "svg_html": "<svg viewBox=\"54 14 352 142\" width=\"100%\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\">\n\n          <g transform=\"translate(60, 20)\">\n            <rect x=\"0\" y=\"0\" width=\"340\" height=\"130\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.8\"/>\n            <rect x=\"40\" y=\"15\" width=\"260\" height=\"55\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n            <text x=\"170\" y=\"45\" font-size=\"11\" font-weight=\"800\" fill=\"#0f172a\" text-anchor=\"middle\">Projector View: Audience sees this slide</text>\n            <rect x=\"40\" y=\"78\" width=\"260\" height=\"40\" rx=\"4\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n            <text x=\"170\" y=\"102\" font-size=\"10.5\" font-weight=\"800\" fill=\"#b45309\" text-anchor=\"middle\">Speaker Notes: Only visible to presenter on laptop</text>\n          </g>\n</svg>",
    "title": "Presentations: Speaker Notes",
    "watch_out": "Make sure your display is set to 'Extend' rather than 'Duplicate' to use Presenter View."
